import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

/** Sound effects, generated by tools/make-sounds.py. */
const SOURCES = {
  eat: require('../../assets/sounds/eat.wav'),
  bonus: require('../../assets/sounds/bonus.wav'),
  'bonus-spawn': require('../../assets/sounds/bonus-spawn.wav'),
  die: require('../../assets/sounds/die.wav'),
  turn: require('../../assets/sounds/turn.wav'),
  click: require('../../assets/sounds/click.wav'),
  count: require('../../assets/sounds/count.wav'),
  go: require('../../assets/sounds/go.wav'),
  win: require('../../assets/sounds/win.wav'),
} as const;

export type SoundName = keyof typeof SOURCES;

const players: Partial<Record<SoundName, AudioPlayer>> = {};
let enabled = true;
let configured = false;

export function setSoundEnabled(on: boolean) {
  enabled = on;
}

function player(name: SoundName): AudioPlayer | null {
  try {
    if (!configured) {
      configured = true;
      // Game sounds should never stop the player's music.
      setAudioModeAsync({ interruptionMode: 'mixWithOthers', playsInSilentMode: false }).catch(() => {});
    }
    players[name] ??= createAudioPlayer(SOURCES[name]);
    return players[name]!;
  } catch {
    return null;
  }
}

/** Loads every effect up front so the first bite is not delayed. */
export function preloadSounds() {
  for (const name of Object.keys(SOURCES) as SoundName[]) player(name);
}

export function play(name: SoundName) {
  if (!enabled) return;
  const p = player(name);
  if (!p) return;
  try {
    p.seekTo(0).catch(() => {});
    p.play();
  } catch {
    // Audio is a nicety; never let it break the game.
  }
}
